'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var isComplex128 = require( '@stdlib/assert/is-complex128' );
var isComplex64 = require( '@stdlib/assert/is-complex64' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var ITERATOR_SYMBOL = require( '@stdlib/symbol/iterator' );
var factory = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the returned constructor is a `values` method (complex128)', function test( t ) {
	var Complex128Array = factory( 'complex128' );
	t.strictEqual( hasOwnProp( Complex128Array.prototype, 'values' ), true, 'has property' );
	t.strictEqual( isFunction( Complex128Array.prototype.values ), true, 'has method' );
	t.end();
});

