tape( 'if an environment supports `Symbol.iterator`, the method returns an iterable (complex128)', function test( t ) {
	var Complex128Array;
	var arr;
	var buf;
	var it1;
	var it2;
	var v1;
	var v2;
	var i;

	if ( !ITERATOR_SYMBOL ) {
		t.ok( true, 'environment does not support Symbol.iterator' );
		t.end();
		return;
	}
	Complex128Array = factory( 'complex128' );

	buf = [ 1.0, -1.0, 2.0, -2.0, 3.0, -3.0, 4.0, -4.0 ];
	arr = new Complex128Array( buf );

	it1 = arr.values();
	t.strictEqual( typeof it1[ ITERATOR_SYMBOL ], 'function', 'has method' );
	t.strictEqual( it1[ ITERATOR_SYMBOL ].length, 0, 'has zero arity' );

	it2 = it1[ ITERATOR_SYMBOL ]();
	t.strictEqual( typeof it2, 'object', 'returns expected value' );
	t.strictEqual( typeof it2.next, 'function', 'has `next` method' );
	t.strictEqual( typeof it2.return, 'function', 'has `return` method' );

	for ( i = 0; i < arr.length; i++ ) {
		v1 = it1.next().value;
		v2 = it2.next().value;
		t.strictEqual( real( v1 ), real( v2 ), 'returns expected value' );
		t.strictEqual( imag( v1 ), imag( v2 ), 'returns expected value' );
	}
	t.end();
});

